-- Disposable PostgreSQL 17 baseline shaped from the inspected LIVE schema.
-- This fixture contains representative existing LIVE rows only; it is not a
-- backup and is never connected to either Supabase project.

create role anon nologin;
create role authenticated nologin;
create role service_role nologin bypassrls;

create schema auth;
create table auth.users (
  id uuid primary key
);
create or replace function auth.uid()
returns uuid
language sql
stable
as $$
  select nullif(current_setting('request.jwt.claim.sub', true), '')::uuid;
$$;

create schema storage;
create table storage.buckets (
  id text primary key,
  name text not null,
  public boolean not null default false,
  file_size_limit bigint,
  allowed_mime_types text[]
);
create table storage.objects (
  id uuid primary key default gen_random_uuid(),
  bucket_id text not null references storage.buckets(id),
  name text not null,
  owner_id uuid,
  created_at timestamptz not null default now()
);
alter table storage.objects enable row level security;
grant usage on schema storage to authenticated;
grant select, insert, delete on storage.objects to authenticated;
grant select on storage.buckets to authenticated;

create table public.learning_topics (
  id bigint generated by default as identity primary key,
  student text not null,
  subject text not null,
  subvak text not null default '',
  created_at timestamptz not null default now(),
  archived boolean not null default false,
  deleted boolean not null default false,
  unique (student, subject, subvak)
);

create table public.lessons (
  id bigint generated by default as identity primary key,
  subject text not null,
  title text not null,
  type text not null default 'words',
  created_at timestamptz,
  student text,
  archived boolean not null default false,
  explanation text not null default '',
  ai_instruction text not null default '',
  subvak text,
  ai_check_answers boolean not null default false,
  editor_labels jsonb,
  deleted boolean not null default false,
  learning_topic_id bigint references public.learning_topics(id) on delete set null,
  sort_order integer not null default 0
);

create table public.lesson_items (
  id bigint generated by default as identity primary key,
  lesson_id bigint references public.lessons(id) on delete cascade,
  question text not null,
  answer text not null,
  sort_order integer default 0,
  question_parts jsonb,
  answer_parts jsonb,
  hint text,
  min_words integer not null default 0,
  required_terms text[] not null default '{}'::text[],
  response_type text not null default 'text'
    check (response_type = any (array['text','number','fraction','multiple_choice']::text[])),
  answer_options jsonb not null default '[]'::jsonb,
  difficulty text check (difficulty is null or difficulty = any (array['hard','harder']::text[]))
);

create table public.test_attempts (
  id bigint generated by default as identity primary key,
  lesson_id bigint not null references public.lessons(id) on delete restrict,
  student text not null,
  score integer not null default 0 check (score >= 0),
  total_questions integer not null default 0 check (total_questions >= 0),
  started_at timestamptz not null default now(),
  completed_at timestamptz,
  is_test boolean not null default true,
  created_at timestamptz not null default now(),
  check (score <= total_questions)
);

create table public.test_attempt_answers (
  id bigint generated by default as identity primary key,
  attempt_id bigint not null references public.test_attempts(id) on delete cascade,
  question_order integer not null default 0 check (question_order >= 0),
  question text not null,
  expected_answer text,
  given_answer text,
  is_correct boolean not null default false,
  question_type text not null default 'text',
  answered_at timestamptz not null default now()
);

create table public.game_results (
  id bigint generated by default as identity primary key,
  lesson_id bigint not null references public.lessons(id) on delete cascade,
  student text not null,
  score integer not null default 0 check (score >= 0),
  played_at timestamptz not null default now(),
  game_key text not null check (game_key = any (array[
    'double-or-nothing'::text,'memory'::text,'flash-question'::text,
    'tic-tac-toe'::text,'drop4'::text,'connect-the-dots'::text,
    'word-reveal'::text,'word-chase'::text,'lexo'::text
  ]))
);

create table public.lesson_order (
  id bigint generated by default as identity primary key,
  student text not null,
  subject text not null,
  lesson_id bigint not null references public.lessons(id) on delete cascade,
  position integer not null default 0,
  created_at timestamptz not null default now(),
  unique (student, subject, lesson_id)
);

create table public.game_access_settings (
  student text primary key,
  required_tests integer not null default 10 check (required_tests >= 1),
  minimum_score integer not null default 9 check (minimum_score >= 0),
  updated_at timestamptz not null default now()
);

create table public.game_access_cycles (
  student text primary key,
  cycle integer not null default 1 check (cycle >= 1),
  updated_at timestamptz not null default now()
);

create table public.game_access_cycle_tests (
  student text not null,
  cycle integer not null check (cycle >= 1),
  lesson_id bigint not null references public.lessons(id) on delete restrict,
  qualifying_score numeric not null check (qualifying_score >= 0),
  credited_at timestamptz not null default now(),
  primary key (student, cycle, lesson_id)
);

create table public.game_access_state (
  student text not null,
  game_key text not null,
  unlocked boolean not null default false,
  updated_at timestamptz not null default now(),
  primary key (student, game_key)
);
create unique index game_access_state_one_unlocked_game_per_student
  on public.game_access_state(student)
  where unlocked is true and game_key <> 'double-or-nothing';

create table public.skill_assignments (
  id bigint generated by default as identity primary key,
  student text not null,
  skill_id text not null,
  enabled boolean not null default true,
  settings jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.skill_definitions (
  id text primary key,
  category text not null,
  title text not null,
  description text not null default '',
  definition jsonb not null default '{}'::jsonb,
  enabled boolean not null default true,
  sort_order integer not null default 0,
  updated_at timestamptz not null default now(),
  created_at timestamptz not null default now(),
  archived_at timestamptz,
  trashed_at timestamptz
);

create table public.challenge_configurations (
  id bigint generated by default as identity primary key,
  challenge_key text not null unique,
  enabled boolean not null default true,
  unlock_policy jsonb not null default '{"type":"assessment-score","minimumScore":10,"allowedLessonTypes":[]}'::jsonb,
  ai_settings jsonb not null default '{}'::jsonb,
  game_settings jsonb not null default '{}'::jsonb,
  updated_at timestamptz not null default now(),
  created_at timestamptz not null default now()
);

alter table public.lessons enable row level security;
alter table public.lesson_items enable row level security;
alter table public.test_attempts enable row level security;
alter table public.test_attempt_answers enable row level security;
alter table public.game_results enable row level security;
alter table public.lesson_order enable row level security;
alter table public.game_access_settings enable row level security;
alter table public.game_access_cycles enable row level security;
alter table public.game_access_cycle_tests enable row level security;
alter table public.game_access_state enable row level security;
alter table public.skill_assignments enable row level security;
alter table public.skill_definitions enable row level security;
alter table public.challenge_configurations enable row level security;
alter table public.learning_topics enable row level security;

grant all on all tables in schema public to anon, authenticated;

